previewCss:
.darma-loader-yoyo-drop {
  position: relative;
  width: 24px;
  height: 52px;
}
.darma-loader-yoyo-drop::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 2px;
  margin-left: -1px;
  background: #c7d2fe;
  animation: darma-loader-yoyo-drop-str 1s ease-in-out infinite;
}
.darma-loader-yoyo-drop i {
  position: absolute;
  left: 50%;
  width: 22px;
  height: 22px;
  margin-left: -11px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  box-shadow: inset 0 0 0 3px #4338ca;
  animation: darma-loader-yoyo-drop-drop 1s ease-in-out infinite, darma-loader-yoyo-drop-spin 0.5s linear infinite;
}
@keyframes darma-loader-yoyo-drop-drop {
  0%, 100% { top: 8px; }
  50% { top: 28px; }
}
@keyframes darma-loader-yoyo-drop-str {
  0%, 100% { height: 16px; }
  50% { height: 36px; }
}
@keyframes darma-loader-yoyo-drop-spin { to { transform: rotate(360deg); } }

